import{_ as o,a0 as p,w as n,s as i,I as r,x as t,a1 as l,A as a,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse(`{"title":"“硅谷的女兒”的成才之路 | LCTT x X-CMD","titleTemplate":false,"description":"“硅谷的女兒”的成才之路 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“硅谷的女兒”的成才之路 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“硅谷的女兒”的成才之路 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20160505 A daughter of Silicon Valley shares her 'nerd' story","title":"“硅谷的女兒”的成才之路","tag":"201612","desc":""},"relativePath":"201612/20160505 A daughter of Silicon Valley shares her 'nerd' story.md","filePath":"[post].md"}`),d={name:"201612/20160505 A daughter of Silicon Valley shares her 'nerd' story.md"};function u(f,e,h,T,g,C){const s=p("Link");return n(),i("div",null,[e[19]||(e[19]=r("h1",{id:"硅谷的女兒-的成才之路",tabindex:"-1"},[t("“硅谷的女兒”的成才之路 "),r("a",{class:"header-anchor",href:"#硅谷的女兒-的成才之路","aria-label":"Permalink to ““硅谷的女兒”的成才之路”"},"​")],-1)),e[20]||(e[20]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/myopensourcestory.png?itok=6TXlAkFi",alt:""})],-1)),r("p",null,[e[1]||(e[1]=t("在 2014 年，為了對網上一些關於在科技行業女性稀缺的評論作出回應，我的同事 ",-1)),l(s,{href:"http://skinnywhitegirl.com/blog/my-nerd-story/1101/"},{default:a(()=>[...e[0]||(e[0]=[t("Crystal Beasley",-1)])]),_:1}),e[2]||(e[2]=t(" 倡議在科技/信息安全方面工作的女性在網絡上分享自己的“成才之路”。這篇文章就是我的故事。我把我的故事與你們分享是因為我相信榜樣的力量，也相信一個人有多種途徑，選擇一個讓自己滿意的有挑戰性的工作以及可以實現目標的人生。",-1))]),e[21]||(e[21]=m('<h3 id="和電腦相伴的童年" tabindex="-1">和電腦相伴的童年 <a class="header-anchor" href="#和電腦相伴的童年" aria-label="Permalink to “和電腦相伴的童年”">​</a></h3><p>我可以説是硅谷的女兒。我的故事不是一個從科技業餘愛好轉向專業的故事，也不是從小就專注於這份事業的故事。這個故事更多的是關於環境如何塑造你 — 通過它的那種已然存在的文化來改變你，如果你想要被改變的話。這不是從小就開始努力併為一個明確的目標而奮鬥的故事，我意識到，這其實是享受了一些特權的成長故事。</p><p>我出生在曼哈頓，但是我在新澤西州長大，因為我的爸爸退伍後，在那裏的羅格斯大學攻讀計算機科學的博士學位。當我四歲時，學校裏有人問我爸爸幹什麼謀生時，我説，“他就是看電視和捕捉小蟲子，但是我從沒有見過那些小蟲子”（LCTT 譯註：小蟲子，bug）。他在家裏有一台啞終端（LCTT 譯註：就是那台“電視”），這大概與他在 Bolt Beranek Newman 公司的工作有關，做關於早期互聯網人工智能方面的工作。我就在旁邊看着。</p><p>我沒能玩上父親的會抓小蟲子的電視，但是我很早就接觸到了技術領域，我很珍惜這個禮物。提早的薰陶對於一個未來的高手是十分必要的 — 所以，請花時間和你的小孩談談你在做的事情！</p><p><img src="https://opensource.com/sites/default/files/resize/moss-520x433.png" alt=""></p><p><em>我父親的終端和這個很類似 —— 如果不是這個的話 CC BY-SA 4.0</em></p><p>當我六歲時，我們搬到了加州。父親在施樂的帕克研究中心（Xerox PARC）找到了一個工作。我記得那時我認為這個城市一定有很多熊，因為在它的旗幟上有一個熊。在1979年，帕洛阿圖市還是一個大學城，還有果園和開闊地帶。</p><p>在 Palo Alto 的公立學校待了一年之後，我的姐姐和我被送到了“半島學校”，這個“民主典範”學校對我造成了深刻的影響。在那裏，好奇心和創新意識是被高度推崇的，教育也是由學生自己分組討論決定的。在學校，我們很少能看到叫做電腦的東西，但是在家就不同了。</p><p>在父親從施樂辭職之後，他就去了蘋果公司，在那裏他工作使用並帶回家讓我玩的第一批電腦就是：Apple II 和 LISA。我的父親在最初的 LISA 的研發團隊。我直到現在還深刻的記得他讓我們一次又一次的“玩”鼠標訓練的場景，因為他想讓我的 3 歲大的妹妹也能對這個東西覺得好用 —— 她也確實那樣。</p><p><img src="https://opensource.com/sites/default/files/resize/600px-apple_lisa-520x520.jpg" alt=""></p><p><em>我們的 LISA 看起來就像這樣。誰看到鼠標哪兒去了？CC BY-SA 4.0</em></p><p>在學校，我的數學的概念學得不錯，但是基本計算卻慘不忍睹。我的第一個學校的老師告訴我的家長和我，説我的數學很差，還説我很“笨”。雖然我在“常規的”數學項目中表現出色，能理解一個超出 7 歲孩子理解能力的邏輯謎題，但是我不能完成我們每天早上都要做的“練習”。她説我傻，這事我不會忘記。在那之後的十年我都沒能相信自己的邏輯能力和算法的水平。<strong>不要低估你對孩子説的話的影響</strong>。</p><p>在我玩了幾年爸爸的電腦之後，他從 Apple 公司跳槽到了 EA，又跳到了 SGI，我又體驗了他帶回來的新玩意。這讓我們認為我們家的房子是鎮裏最酷的，因為我們在車庫裏有一個能玩 Doom 的 SGI 的機器。我不會太多的編程，但是現在看來，從那些年裏我學到對嘗試新的科技毫不恐懼。同時，我的學文學和教育的母親，成為了一個科技行業的作家，她向我證實了一個人的職業可以改變，而且一個做母親的人可能同時駕馭一個科技職位。我不是説這對她來説很簡單，但是她讓我認為這件事看起來很簡單。你可能會想這些早期的薰陶能把我帶到科技行業，但是它沒有。</p><h3 id="本科時光" tabindex="-1">本科時光 <a class="header-anchor" href="#本科時光" aria-label="Permalink to “本科時光”">​</a></h3><p>我想我要成為一個小學教師，我就讀米爾斯學院就是想要做這個。但是後來我開始研究女性學，後來又研究神學，我這樣做僅僅是由於我自己的一個渴求：我希望能理解人類的意志以及為更好的世界而努力。</p><p>同時，我也感受到了互聯網的巨大力量。在 1991 年，擁有你自己的 UNIX 的賬户，能夠和全世界的人談話，是很令人興奮的事。我僅僅從在互聯網中“玩”就學到了不少，從那些願意回答我提出的問題的人那裏學到的就更多了。這些學習對我的職業生涯的影響不亞於我在正規學校教育之中學到的知識。所有的信息都是有用的。我在一個女子學院度過了學習的關鍵時期，那時是一個傑出的女性在掌管計算機院。在那個寬鬆氛圍的學院，我們不僅被允許，還被鼓勵去嘗試很多的道路（我們能接觸到很多很多的科技，還有聰明人願意幫助我們），我也確實那樣做了。我十分感激當年的教育。在那個學院，我也瞭解了什麼是極客文化。</p><p>之後我去了研究生院去學習女性主義神學，但是技術的氣息已經滲入我的靈魂。當我意識到我不想成為一個教授或者一個學術倫理家時，我離開了學術圈，帶着學校債務和一些想法回到了家。</p><h3 id="新的開端" tabindex="-1">新的開端 <a class="header-anchor" href="#新的開端" aria-label="Permalink to “新的開端”">​</a></h3><p>在 1995 年，我被互聯網連接人們以及分享想法和信息的能力所震驚（直到現在仍是如此）。我想要進入這個行業。看起來我好像要“女承父業”，但是我不知道如何開始。我開始在硅谷做臨時工，從 Sun 微系統公司得到我的第一個“真正”技術職位前嘗試做了一些事情（為半導體數據公司寫最基礎的資料庫，技術手冊印發前的事務，備份工資單的存跟）。這些事很讓人激動。（畢竟，我們是“.com”中的那個”點“）。</p><p>在 Sun 公司，我努力學習，儘可能多的嘗試新事物。我的第一個工作是<ruby>網頁化<rt> HTMLing</rt></ruby>（啥？這居然是一個詞！）白皮書，以及為 Beta 程序修改一些基礎的服務工具（大多數是 Perl 寫的）。後來我成為 Solaris beta 項目組中的項目經理，並在 Open Solaris 的 Beta 版運行中感受到了開源的力量。</p><p>在那裏我做的最重要的事情就是學習。我發現在同樣重視工程和教育的地方有一種氣氛，在那裏我的問題不再顯得“傻”。我很慶幸我選對了導師和朋友。在決定休第二個孩子的產假之前，我上每一堂我能上的課程，讀每一本我能讀的書，嘗試自學我在學校沒有學習過的技術，商業以及項目管理方面的技能。</p><h3 id="重回工作" tabindex="-1">重回工作 <a class="header-anchor" href="#重回工作" aria-label="Permalink to “重回工作”">​</a></h3><p>當我準備重新工作時，Sun 公司已經不再是合適的地方了。所以，我整理了我的聯繫信息（網絡幫到了我），利用我的溝通技能，最終獲得了一個管理互聯網門户的長期合同（2005 年時，一切皆門户），並且開始瞭解 CRM、發佈產品的方式、本地化、網絡等知識。我講這麼多背景，主要是我的嘗試以及失敗的經歷，和我成功的經歷同等重要，從中學到很多。我也認為我們需要這個方面的榜樣。</p><p>從很多方面來看，我的職業生涯的第一部分是我的技術教育。時變勢移 —— 我在幫助組織中的女性和其他弱勢羣體，但是並沒有看出為一個技術行業的女性有多難。當時無疑我沒有看到這個行業的缺陷，但是現在這個行業更加的厭惡女性，一點沒有減少。</p><p>在這些事情之後，我還沒有把自己當作一個標杆，或者一個高級技術人員。當我在父母圈子裏認識的一位極客朋友鼓勵我申請一個看起來定位十分模糊且技術性很強的開源的非盈利基礎設施機構（互聯網系統協會 ISC，它是廣泛部署的開源 DNS 名稱服務器 BIND 的締造者，也是 13 台根域名服務器之一的運營商）的產品經理時，我很震驚。有很長一段時間，我都不知道他們為什麼要僱傭我！我對 DNS、基礎設備，以及協議的開發知之甚少，但是我再次遇到了老師，並再度開始飛速發展。我花時間出差，在關鍵流程攻關，搞清楚如何與高度國際化的團隊合作，解決麻煩的問題，最重要的是，擁抱支持我們的開源和充滿活力的社區。我幾乎重新學了一切，通過試錯的方式。我學習如何構思一個產品。如何通過建設開源社區，領導那些有這特定才能，技能和耐心的人，是他們給了產品價值。</p><h3 id="成為別人的導師" tabindex="-1">成為別人的導師 <a class="header-anchor" href="#成為別人的導師" aria-label="Permalink to “成為別人的導師”">​</a></h3>',26)),r("p",null,[e[4]||(e[4]=t("當我在 ISC 工作時，我通過 ",-1)),l(s,{href:"https://www.techwomen.org/mentorship/why-i-keep-coming-back-to-mentor-with-techwomen"},{default:a(()=>[...e[3]||(e[3]=[t("TechWomen 項目",-1)])]),_:1}),e[5]||(e[5]=t(" （一個讓來自中東和北非的技術行業的女性到硅谷來接受教育的計劃），我開始喜歡教學生以及支持那些技術女性，特別是在開源行業中奮鬥的。也正是從這時起我開始相信自己的能力。我還需要學很多。",-1))]),e[22]||(e[22]=r("p",null,"當我第一次讀 TechWomen 關於導師的廣告時，我根本不認為他們會約我面試！我有冒名頂替綜合症。當他們邀請我成為第一批導師（以及以後六年每年的導師）時，我很震驚，但是現在我學會了相信這些都是我努力得到的待遇。冒名頂替綜合症是真實的，但是隨着時間過去我就慢慢名副其實了。",-1)),e[23]||(e[23]=r("h3",{id:"現在",tabindex:"-1"},[t("現在 "),r("a",{class:"header-anchor",href:"#現在","aria-label":"Permalink to “現在”"},"​")],-1)),e[24]||(e[24]=r("p",null,"最後，我不得不離開我在 ISC 的工作。幸運的是，我的工作以及我的價值讓我進入了 Mozilla ，在這裏我的努力和我的幸運讓我在這裏承擔着重要的角色。現在，我是一名支持多樣性與包容的高級項目經理。我致力於構建一個更多樣化，更有包容性的 Mozilla ，站在之前的做同樣事情的巨人的肩膀上，與最聰明友善的人們一起工作。我用我的激情來讓人們找到貢獻一個世界需要的互聯網的有意義的方式：這讓我興奮了很久。當我爬上山峯，我能極目四望！",-1)),e[25]||(e[25]=r("p",null,"通過對組織和個人行為的干預來獲取一種改變文化的新方式，這和我的人生軌跡有着不可思議的聯繫 —— 從我的早期的學術生涯，到職業生涯再到現在。每天都是一個新的挑戰，我想這是我喜歡在科技行業工作，尤其是在開放互聯網工作的理由。互聯網天然的多元性是它最開始吸引我的原因，也是我還在尋求的 —— 所有人都有機會和獲取資源的可能性，無論背景如何。榜樣、導師、資源，以及最重要的，尊重，是不斷發展技術和開源文化的必要組成部分，實現我相信它能實現的所有事 —— 包括給所有人平等的接觸機會。",-1)),e[26]||(e[26]=r("hr",null,null,-1)),r("p",null,[e[7]||(e[7]=t("via: ",-1)),l(s,{href:"https://opensource.com/life/16/5/my-open-source-story-larissa-shapiro"},{default:a(()=>[...e[6]||(e[6]=[t("https://opensource.com/life/16/5/my-open-source-story-larissa-shapiro",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=t("作者：",-1)),l(s,{href:"https://opensource.com/users/larissa-shapiro"},{default:a(()=>[...e[8]||(e[8]=[t("Larissa Shapiro",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),l(s,{href:"https://github.com/name1e5s"},{default:a(()=>[...e[9]||(e[9]=[t("name1e5s",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),l(s,{href:"https://github.com/jasminepeng"},{default:a(()=>[...e[10]||(e[10]=[t("jasminepeng",-1)])]),_:1})]),r("p",null,[e[16]||(e[16]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創翻譯，",-1)),l(s,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const x=o(d,[["render",u]]);export{y as __pageData,x as default};
